<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{register}from'../api/client';const router=useRouter(),form=ref({username:'',password:'',display_name:'',email:''}),error=ref(''),loading=ref(false);async function submit(){loading.value=true;error.value='';try{await register(form.value);router.push('/login')}catch(e:any){error.value=e.response?.data?.error?.message||'注册失败'}finally{loading.value=false}}</script>
<template><div class="login-page"><section class="login-showcase"><div class="showcase-copy"><span class="eyebrow">CREATE ACCOUNT</span><h1>创建运营账号<br><em>加入长租管理平台</em></h1><p>注册后的账号由业务管理员配置角色与权限。</p></div></section><section class="login-panel"><div class="login-card"><h2>注册账号</h2><form @submit.prevent="submit"><label>用户名<input v-model="form.username" autocomplete="username"></label><label>显示名称<input v-model="form.display_name"></label><label>邮箱<input v-model="form.email" type="email"></label><label>密码<input v-model="form.password" type="password" autocomplete="new-password"></label><p v-if="error" class="form-error">{{error}}</p><button class="login-button" :disabled="loading">{{loading?'提交中...':'完成注册'}}</button><button type="button" class="ghost-button" @click="router.push('/login')">返回登录</button></form></div></section></div></template>
